// Phase-0 baseline generator. Loads the REAL frontend/src/metrics.ts on frontend/public/sky.json.
// Run (Node >= 22.6 with type stripping; Node 24 needs no flag):
//   node tests/fixtures/make-baseline.mjs            -> prints JSON
//   node tests/fixtures/make-baseline.mjs --write    -> writes tests/fixtures/baseline.json
// Optional: --metrics <path to an older metrics.ts> to reproduce a historical version (not written).
import { readFileSync, writeFileSync } from 'node:fs'
import { execSync } from 'node:child_process'
import { pathToFileURL, fileURLToPath } from 'node:url'
import path from 'node:path'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
const argv = process.argv.slice(2)
const mi = argv.indexOf('--metrics')
const metricsPath = mi >= 0 ? path.resolve(argv[mi + 1]) : path.join(root, 'frontend/src/metrics.ts')
const M = await import(pathToFileURL(metricsPath).href)
const sky = JSON.parse(readFileSync(path.join(root, 'frontend/public/sky.json'), 'utf8'))

const CONFIGS = [
  { id: 'a', date: '2026-11-15', days: 365 },
  { id: 'b', date: '2027-06-23', days: 30 },
]

export function run() {
  const out = {}
  for (const c of CONFIGS) {
    const span = M.spanFor(sky, c.date, c.days)
    const rows = sky.sites.map(site => ({ site, m: M.siteMetrics(site, span, sky.meta.step_hours) }))
    const verd = M.verdicts ? M.verdicts(rows.map(r => ({ id: r.site.id, m: r.m }))) : {}
    const bestDark = M.bestDarkHours ? M.bestDarkHours(rows.map(r => r.m)) : Math.min(...rows.map(r => r.m.longestDarkHours))
    const topSun = Math.max(...rows.map(r => r.m.sunPct)), topEarth = Math.max(...rows.map(r => r.m.earthPct))
    const sunClose = M.closeCall ? M.closeCall(rows.map(r => r.m.sunPct)).close : false
    const earthClose = M.closeCall ? M.closeCall(rows.map(r => r.m.earthPct)).close : false
    const near = (top, v) => M.nearTop ? M.nearTop(top, v) : false
    out[`${c.date}+${c.days}d`] = {
      window: { startIndex: span.start, endIndex: span.end },
      sunCloseCall: sunClose, earthCloseCall: earthClose,
      sites: Object.fromEntries(rows.map(({ site, m }) => {
        const v = verd[site.id] ?? null
        const label = v ? M.VERDICT_TEXT?.[v] ?? v
          : ((sunClose && near(topSun, m.sunPct)) || (earthClose && near(topEarth, m.earthPct))) ? 'Too close to call' : 'No top score'
        return [site.id, {
          sunPct: m.sunPct, earthPct: m.earthPct,
          longestDarkHours: m.longestDarkHours, darkCut: m.darkCut,
          verdict: label,
          stars: {
            sun: !sunClose && m.sunPct === topSun,
            earth: !earthClose && m.earthPct === topEarth,
            // main: star only on an uncut night equal to the shortest uncut night; pre-ccaf310: plain minimum
            darkness: M.bestDarkHours ? (!m.darkCut && m.longestDarkHours === bestDark) : m.longestDarkHours === bestDark,
          },
        }]
      })),
    }
  }
  return out
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = run()
  if (mi >= 0) { console.log(JSON.stringify(result, null, 1)) }
  else {
    const commit = execSync('git rev-parse HEAD', { cwd: root }).toString().trim()
    const doc = {
      note: 'Baseline of the pre-upgrade app (sky.json v1, flat 0 deg horizon, centre-of-disc, hourly). Generated by tests/fixtures/make-baseline.mjs from frontend/src/metrics.ts. generating_commit is the HEAD the script ran on (code under frontend/src unchanged since 724192e unless noted).',
      generating_commit: commit, script: 'tests/fixtures/make-baseline.mjs',
      sky_json_meta: sky.meta, configs: result,
    }
    if (argv.includes('--write')) writeFileSync(path.join(root, 'tests/fixtures/baseline.json'), JSON.stringify(doc, null, 1) + '\n')
    else console.log(JSON.stringify(doc, null, 1))
  }
}
